tools.exec_command({cmd:"rtk proxy bat --paging=never docs/specs/SPEC-RELEASE-PRODUCT-MODEL-001.json docs/specs/SPEC-RELEASE-CONVERGENCE-002.json docs/architecture/model.json",workdir:"/private/tmp/callisto-release-recovery",max_output_tokens:22000}),
tools.exec_command({cmd:"rtk proxy bat --paging=never justfile .moon/tasks.yml crates/callisto-graph/src/commands/registry_argv.rs crates/callisto-graph/src/config/raw.rs crates/callisto-graph/src/config/resolve.rs callisto.toml",workdir:"/private/tmp/callisto-release-recovery",max_output_tokens:18000}),
tools.exec_command({cmd:"rtk proxy rg -n 'ReleaseReceiptV1|ArtifactManifestV1|ArtifactSlotId|ReleaseOperationId|validate_release_artifacts|execute_release_with_artifacts|PreparedReleaseOperation|release.?unit|RawPackage|PackageConfig' crates .github scripts",workdir:"/private/tmp/callisto-release-recovery",max_output_tokens:14000})
]);r.forEach(text);

